    int arr[] = {1, 2, 3, 4, 5};
    int n = sizeof(arr) / sizeof(arr[0]);

    ListNode* head = buildList(arr, n);

    std::cout << "Original list: ";
    printList(head);

    ListNode* newHead = reverseLinkedList(head);

    std::cout << "Reversed list:  ";
    printList(newHead);

    freeList(newHead);

