import csv
import sys


def compute_column_averages(filepath: str) -> dict:
    """
    Read a CSV file and compute the average of each numeric column.

    Args:
        filepath: Path to the CSV file.

    Returns:
        A dictionary mapping column names to their averages.
    """
    column_sums = {}
    column_counts = {}

    with open(filepath, newline='', encoding='utf-8') as csvfile:
        reader = csv.DictReader(csvfile)
        fieldnames = reader.fieldnames
        if not fieldnames:
            return {}

        for row in reader:
            for col in fieldnames:
                value = row[col]
                if value is None or value.strip() == '':
                    continue
                try:
                    num = float(value.strip())
                    if col not in column_sums:
                        column_sums[col] = 0.0
                        column_counts[col] = 0
                    column_sums[col] += num
                    column_counts[col] += 1
                except (ValueError, TypeError):
                    # Skip non-numeric values
                    continue

    averages = {}
    for col in fieldnames:
        if col in column_sums and column_counts[col] > 0:
            averages[col] = column_sums[col] / column_counts[col]

    return averages


def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <csv_file>")
        sys.exit(1)

    filepath = sys.argv[1]

    try:
        averages = compute_column_averages(filepath)
    except FileNotFoundError:
        print(f"Error: File '{filepath}' not found.")
        sys.exit(1)
    except Exception as e:
        print(f"Error reading file: {e}")
        sys.exit(1)

    if not averages:
        print("No numeric columns found.")
        return

    print("Column Averages:")
    for col, avg in averages.items():
        print(f"  {col}: {avg:.4f}")


if __name__ == "__main__":
    main()
